window.PIXEL_CHAPTERS=[{"title":"Le jardin s’éveille","ref":"Genèse 2,8–15","mission":"Explore les sentiers et découvre pourquoi le jardin est confié à l’être humain.","intro":"Le récit biblique situe un jardin planté par Dieu en Éden. Adam y reçoit une tâche : le cultiver et le garder.","seed":226,"size":[21,17],"events":[{"title":"Un jardin en Éden","ref":"Genèse 2,8–9","body":"Dieu plante un jardin en Éden. Le texte raconte qu’il y fait pousser des arbres beaux à voir et bons à manger.","notice":"Les ponts, fleurs et animaux de notre labyrinthe sont des inventions graphiques."},{"title":"L’eau du jardin","ref":"Genèse 2,10–14","body":"Un fleuve sort d’Éden pour arroser le jardin. Le récit nomme quatre cours d’eau.","notice":"Les cascades dessinées dans le jeu ne représentent pas une carte géographique réelle."},{"title":"Cultiver et garder","ref":"Genèse 2,15","body":"Dieu place l’homme dans le jardin pour le cultiver et le garder. Prendre soin de ce qui nous est confié est la mission présentée ici.","notice":"Les livres lumineux sont des objets inventés pour apprendre en jouant."}],"question":{"ask":"Quelle tâche Dieu confie-t-il à Adam dans le jardin ?","answers":["Construire une ville","Cultiver et garder le jardin","Chercher un trésor"],"correct":1,"explain":"Genèse 2,15 dit qu’Adam est placé dans le jardin pour le cultiver et le garder."},"reflection":"À retenir : le jardin est un cadeau, et Adam reçoit la responsabilité d’en prendre soin."},{"title":"Une rencontre merveilleuse","ref":"Genèse 2,18–25","mission":"Rencontre les animaux, puis découvre le récit de la création de la femme.","intro":"Adam découvre les êtres vivants. Le récit raconte ensuite l’arrivée de la femme, présentée comme une aide qui lui corresponde.","seed":452,"size":[23,19],"events":[{"title":"Il n’est pas bon d’être seul","ref":"Genèse 2,18","body":"Dieu déclare qu’il n’est pas bon que l’homme soit seul. Il annonce une aide qui lui corresponde.","notice":"Ce chapitre présente une scène biblique, pas une règle sur la valeur des personnes seules."},{"title":"Les animaux reçoivent un nom","ref":"Genèse 2,19–20","body":"Les animaux sont présentés à l’homme, qui leur donne des noms. Le récit souligne qu’aucun ne correspond à l’aide recherchée.","notice":"Les animaux dessinés sont des illustrations, pas une liste zoologique du texte."},{"title":"La femme est créée","ref":"Genèse 2,21–23","body":"Dieu fait tomber l’homme dans un profond sommeil. Il forme la femme et la conduit vers lui. Adam se réjouit de la reconnaître comme semblable à lui.","notice":"Ève devient un personnage sélectionnable après ce chapitre, afin de respecter la chronologie du récit."}],"question":{"ask":"Selon Genèse 2, que reconnaît Adam lorsqu’il voit la femme ?","answers":["Qu’elle lui ressemble et lui correspond","Qu’elle est un animal nouveau","Qu’il ne la connaît pas"],"correct":0,"explain":"Genèse 2,23 présente la joie d’Adam devant celle qu’il reconnaît comme « os de mes os et chair de ma chair »."},"reflection":"À retenir : le récit insiste sur la rencontre, la relation et la dignité commune de l’homme et de la femme."},{"title":"L’arbre et la consigne","ref":"Genèse 2,9.16–17 ; 3,1–3","mission":"Découvre les instructions données dans le jardin et observe l’arbre du récit.","intro":"Le jardin comporte de nombreux arbres. Le texte met en relief une consigne concernant un arbre particulier. Le fruit n’est pas identifié comme une pomme dans la Bible.","seed":680,"size":[25,21],"events":[{"title":"Plusieurs arbres","ref":"Genèse 2,9","body":"Le récit mentionne l’arbre de vie et l’arbre de la connaissance du bien et du mal, au milieu du jardin.","notice":"Dans nos illustrations, les fruits rouges sont imaginés. La Bible ne dit pas que le fruit était une pomme."},{"title":"Une liberté et une limite","ref":"Genèse 2,16–17","body":"Dieu permet à l’homme de manger des arbres du jardin, sauf de l’arbre de la connaissance du bien et du mal. Il donne une consigne claire.","notice":"La question de la liberté et de la limite peut être discutée avec un adulte."},{"title":"La question du serpent","ref":"Genèse 3,1–3","body":"Le serpent met en question les paroles de Dieu. La femme rappelle alors la consigne concernant l’arbre.","notice":"Le serpent dessiné n’ajoute aucun dialogue absent du passage biblique."}],"question":{"ask":"Le texte biblique précise-t-il que le fruit défendu était une pomme ?","answers":["Oui, une pomme rouge","Oui, une poire","Non, l’espèce du fruit n’est pas indiquée"],"correct":2,"explain":"Genèse 2–3 parle du fruit de l’arbre, sans préciser une variété. Représenter une pomme relève de la tradition artistique."},"reflection":"À retenir : distinguer les mots de la Bible et les détails ajoutés par les illustrations."},{"title":"Un choix difficile","ref":"Genèse 3,1–13","mission":"Suis les indices pour comprendre le choix, puis découvre ce qui change dans le jardin.","intro":"Le serpent trompe la femme. Adam et Ève mangent du fruit interdit, puis prennent conscience de leur nudité et se cachent.","seed":892,"size":[27,21],"events":[{"title":"Une parole mise en doute","ref":"Genèse 3,1–5","body":"Le serpent contredit les paroles de Dieu et promet une connaissance nouvelle. Le récit présente une tentation qui déforme la consigne.","notice":"Pour réfléchir : toutes les paroles séduisantes sont-elles forcément vraies ?"},{"title":"Le fruit est mangé","ref":"Genèse 3,6–7","body":"La femme prend du fruit et en mange. Elle en donne aussi à l’homme, qui en mange. Ils prennent alors conscience de leur nudité.","notice":"Le texte ne nomme pas le fruit. Le jeu ne te fait pas refaire ce choix."},{"title":"Ils se cachent","ref":"Genèse 3,8–13","body":"Adam et sa femme se cachent après avoir entendu la présence de Dieu dans le jardin. Le récit raconte leurs réponses et leurs responsabilités.","notice":"Le jeu conserve un ton respectueux et n’attribue pas toute la faute à un seul personnage."}],"question":{"ask":"Que font Adam et Ève après avoir mangé le fruit ?","answers":["Ils construisent une arche","Ils se cachent dans le jardin","Ils quittent aussitôt le jardin"],"correct":1,"explain":"Dans Genèse 3,7–8, ils prennent conscience de leur nudité puis se cachent parmi les arbres."},"reflection":"À retenir : le récit montre les conséquences d’une décision et invite à réfléchir à la vérité et à la responsabilité."},{"title":"Un chemin nouveau","ref":"Genèse 3,14–24","mission":"Découvre les conséquences de la désobéissance et la sortie du jardin.","intro":"Le récit décrit des conséquences difficiles, puis le départ d’Adam et Ève hors du jardin d’Éden.","seed":1128,"size":[29,23],"events":[{"title":"Des conséquences","ref":"Genèse 3,14–19","body":"Dieu annonce des conséquences au serpent, à la femme et à l’homme. Le travail de la terre devient difficile et la mort est évoquée.","notice":"Ces passages sont complexes. Les images proposent une lecture adaptée aux enfants, pas une explication théologique exhaustive."},{"title":"Le nom Ève","ref":"Genèse 3,20","body":"L’homme donne à sa femme le nom d’Ève, parce qu’elle est appelée mère de tous les vivants.","notice":"Le texte attribue ce nom à ce moment précis du récit."},{"title":"Des vêtements","ref":"Genèse 3,21","body":"Dieu fait des vêtements de peau pour Adam et sa femme et les habille.","notice":"Les habits de feuilles montrés dans certains dessins sont une représentation de Genèse 3,7, pas de ces nouveaux vêtements."},{"title":"La sortie d’Éden","ref":"Genèse 3,22–24","body":"Dieu fait sortir l’homme du jardin. Des chérubins et la flamme d’une épée gardent le chemin de l’arbre de vie.","notice":"La porte monumentale représentée dans l’illustration est inventée : la Bible ne décrit pas un portail doré."}],"question":{"ask":"Qui garde le chemin vers l’arbre de vie à la fin du récit ?","answers":["Des pêcheurs","Des soldats du palais","Des chérubins et une épée flamboyante"],"correct":2,"explain":"Genèse 3,24 mentionne les chérubins et la flamme d’une épée qui garde le chemin de l’arbre de vie."},"reflection":"À retenir : l’histoire se termine hors du jardin. Cette page invite à continuer la découverte du grand récit biblique."}];
